// AsChoiceAnswer returns the union data inside the Answer as a ChoiceAnswer
func (t Answer) AsChoiceAnswer() (ChoiceAnswer, error) {
	var body ChoiceAnswer
	err := json.Unmarshal(t.union, &body)
	return body, err
}

// FromChoiceAnswer overwrites any union data inside the Answer as the provided ChoiceAnswer
func (t *Answer) FromChoiceAnswer(v ChoiceAnswer) error {
	b, err := json.Marshal(v)
	if err != nil {
		return err
	}
	b, err = runtime.JSONMerge(b, []byte(`{"type":"choice"}`))
	t.union = b
	return err
}

// MergeChoiceAnswer performs a merge with any union data inside the Answer, using the provided ChoiceAnswer
func (t *Answer) MergeChoiceAnswer(v ChoiceAnswer) error {
	b, err := json.Marshal(v)
	if err != nil {
		return err
	}
	b, err = runtime.JSONMerge(b, []byte(`{"type":"choice"}`))
	if err != nil {
		return err
	}

	merged, err := runtime.JSONMerge(t.union, b)
	t.union = merged
	return err
}

